def cache_sim(capacity, ttl, ops):
    from collections import defaultdict

    # Dictionary to store key -> (value, write_time)
    cache = {}
    # Dictionary to store key -> last_access_time
    access_time = {}
    # Current time
    current_time = [0]
    # Results of get operations
    results = []

    def is_expired(key, current_t):
        if key not in cache:
            return True
        _, write_time = cache[key]
        return current_t >= write_time + ttl

    def clean_expired(current_t):
        # Remove expired entries
        expired_keys = [key for key in cache if is_expired(key, current_t)]
        for key in expired_keys:
            del cache[key]
            del access_time[key]

    def get_lru_key():
        # Return the key with minimum access time
        if not access_time:
            return None
        return min(access_time, key=access_time.get)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            current_time[0] = t
            clean_expired(t)

            # If key already exists, update it
            if key in cache and not is_expired(key, t):
                cache[key] = (value, t)
                access_time[key] = t
            else:
                # If cache is at capacity, evict LRU
                if key not in cache or is_expired(key, t):
                    if len(cache) >= capacity:
                        lru_key = get_lru_key()
                        if lru_key is not None:
                            del cache[lru_key]
                            del access_time[lru_key]

                cache[key] = (value, t)
                access_time[key] = t

        elif op[0] == 'get':
            _, t, key = op
            current_time[0] = t
            clean_expired(t)

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, t):
                value, _ = cache[key]
                access_time[key] = t  # Update last access time
                results.append(value)
            else:
                results.append(-1)

    return results

